// Author: MiYu. Read classic weapon/profile fields once per type and validate live attack target capabilities.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <sstream>

namespace war3 {
namespace {
std::string part(const std::string& value,unsigned index){std::stringstream input(value);std::string result,first;for(unsigned i=0;std::getline(input,result,',');++i){auto begin=result.find_first_not_of(" \t");result=begin==std::string::npos?"":result.substr(begin,result.find_last_not_of(" \t")-begin+1);if(!i)first=result;if(i==index)return result;}return index?first:std::string{};}
std::set<std::string> targets(const std::string& value){std::stringstream input(value);std::set<std::string> result;std::string token;while(std::getline(input,token,',')){auto begin=token.find_first_not_of(" \t");if(begin==std::string::npos)continue;token=token.substr(begin,token.find_last_not_of(" \t")-begin+1);if(token!="_")result.insert(token);}return result;}
unsigned count(float value,unsigned maximum){if(value<0 || value>maximum || value!=std::floor(value))throw std::runtime_error("Weapon integer outside supported range");return unsigned(value);}
}
const std::array<WeaponDefinition,2>& ScriptSession::weapons(std::uint32_t type) {
    if(auto found=weapons_.find(type);found!=weapons_.end())return found->second;auto& data=definitions();std::array<WeaponDefinition,2> result;auto enabled=count(data.number(type,"UnitWeapons","weapsOn"),3);auto profileNumber=[&](const char* key,unsigned index,float fallback){auto text=part(data.field(type,"Profile",key),index);if(text.empty() || text=="_" || text=="-")return fallback;size_t end=0;float value=std::stof(text,&end);if(end!=text.size() || !std::isfinite(value))throw std::runtime_error("Invalid weapon profile number: "+std::string(key));return value;};
    for(unsigned i=0;i<2;++i){auto& w=result[i];w.slot=i;w.enabled=(enabled&(1u<<i))!=0;auto suffix=std::to_string(i+1);auto n=[&](const char* name,float fallback=0){return data.number(type,"UnitWeapons",std::string(name)+suffix,fallback);};w.kind=data.field(type,"UnitWeapons","weapTp"+suffix);if(!w.enabled && (w.kind.empty() || w.kind=="_"))continue;if(w.kind!="normal" && w.kind!="instant" && w.kind!="missile" && w.kind!="artillery" && w.kind!="msplash" && w.kind!="mbounce" && w.kind!="mline" && w.kind!="aline")throw std::runtime_error("Unknown source weapon kind: "+w.kind);auto attack=data.field(type,"UnitWeapons","atkType"+suffix,"normal");constexpr const char* kinds[]={"spells","normal","pierce","siege","magic","chaos","hero"};unsigned kind=7;for(unsigned k=0;k<7;++k)if(attack==kinds[k])kind=k;if(kind==7)throw std::runtime_error("Unknown source attack type: "+attack);w.attackType=kind;w.targets=targets(data.field(type,"UnitWeapons","targs"+suffix));w.splashTargets=targets(data.field(type,"UnitWeapons","splashTargs"+suffix));w.base=n("dmgplus");w.dice=count(n("dice"),1000);w.sides=count(n("sides"),100000);if(w.dice && !w.sides)throw std::runtime_error("Enabled weapon has dice without sides");w.range=n("rangeN");w.minimumRange=data.number(type,"UnitWeapons","minRange");w.rangeBuffer=n("RngBuff");w.cooldown=n("cool",1);w.point=n("dmgpt");w.backswing=n("backSw");w.fullArea=n("Farea");w.halfArea=n("Harea");w.quarterArea=n("Qarea");w.halfFactor=n("Hfact");w.quarterFactor=n("Qfact");w.maxTargets=std::max(1u,count(n("targCount",1),64));w.loss=n("damageLoss");w.spillDistance=n("spillDist");w.spillRadius=n("spillRadius");w.model=part(data.field(type,"Profile","Missileart"),i);if(w.model=="_")w.model.clear();w.speed=profileNumber("Missilespeed",i,0);w.arc=profileNumber("Missilearc",i,0);w.homing=profileNumber("MissileHoming",i,w.kind=="artillery" || w.kind=="aline"?0.f:1.f)!=0;w.launchX=data.number(type,"UnitWeapons","launchX");w.launchY=data.number(type,"UnitWeapons","launchY");w.launchZ=data.number(type,"UnitWeapons","launchZ");w.impactZ=data.number(type,"UnitWeapons","impactZ",60);if(w.range<0 || w.minimumRange<0 || w.cooldown<=0 || w.point<0 || w.backswing<0 || w.speed<0 || w.arc<0 || w.fullArea<0 || w.halfArea<0 || w.quarterArea<0 || w.loss<0 || w.loss>1)throw std::runtime_error("Weapon source range/timing outside supported range");}return weapons_.emplace(type,std::move(result)).first->second;
}
bool ScriptSession::capability(const UnitState& u,const char* code) {if(std::string_view(code)=="Amim")for(auto& [id,b]:u.buffs)if(b.magicImmune)return true;for(auto& [id,level]:u.abilities)if(level>0 && (ObjectData::name(id)==code || definitions().field(id,"AbilityData","code")==code))return true;return false;}
bool ScriptSession::enemy(unsigned owner,unsigned other) const {return owner!=other && !(config_.players[owner].alliances[other]&1);}
bool ScriptSession::weaponTarget(const UnitState& from,const UnitState& to,const WeaponDefinition& w,bool automatic,bool splash) {
    if(sourceAbility(from,"Abun").first && !garrisonCount(from))return false;if((!w.enabled && !(from.technology.weapons&(1u<<w.slot))) || to.removing || to.hidden() || std::bit_cast<float>(to.life.bits())<=0)return false;auto& allowed=splash && !w.splashTargets.empty()?w.splashTargets:w.targets;if(automatic && (to.owner>=13 || !enemy(from.owner,to.owner)))return false;bool restricted=allowed.contains("enemy") || allowed.contains("friend") || allowed.contains("neutral") || allowed.contains("self");bool hostile=enemy(from.owner,to.owner);bool relationship=(allowed.contains("enemy") && hostile) || (allowed.contains("friend") && !hostile) || (allowed.contains("neutral") && to.owner>=12) || (allowed.contains("self") && &from==&to);if(restricted && !relationship)return false;if((allowed.contains("hero") || allowed.contains("nonhero")) && !(to.hero?allowed.contains("hero"):allowed.contains("nonhero")))return false;bool ward=definitions().unitClasses(to.type).find("ward")!=std::string::npos;bool air=to.movementType=="fly";if(ward?!allowed.contains("ward"):air?!allowed.contains("air"):to.building?(!allowed.contains("ground") && !allowed.contains("structure")):!allowed.contains("ground"))return false;if((to.invulnerable || capability(to,"Avul")) && !allowed.contains("invulnerable"))return false;if(w.attackType==4 && capability(to,"Amim"))return false;return true;
}
std::optional<unsigned> ScriptSession::weaponFor(const UnitState& from,const UnitState& to,bool automatic) {auto& values=weapons(from.type);for(unsigned i=0;i<values.size();++i)if(weaponTarget(from,to,values[i],automatic))return i;return {};}
bool ScriptSession::hasWeapon(std::uint32_t handle) {if(!alive(handle,NativeKind::Unit))return false;auto& u=*units_.at(handle);if(sourceAbility(u,"Abun").first && !garrisonCount(u))return false;auto& value=weapons(u.type);return value[0].enabled || value[1].enabled || u.technology.weapons;}
}
